<section class="page-heading"><span class="eyebrow">FIND YOUR NEXT CHAPTER</span><h1><?= e($title) ?></h1><p>A demonstration collection of distinctive spaces and thoughtful possibilities.</p></section>
<div class="page-main search-layout"><aside class="filter-panel"><h3>Refine your search</h3><form action="/properties"><label class="field"><span>Location</span><input name="q" value="<?= e($data['filters']['q'] ?? '') ?>" placeholder="City or neighborhood"></label><label class="field"><span>Purpose</span><select name="purpose"><option value="">Buy & rent</option><?php foreach (['sale'=>'For sale','rent'=>'For rent'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($data['filters']['purpose'] ?? '')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></label><label class="field"><span>Property type</span><select name="type"><option value="">All types</option><?php foreach ($data['types'] as $t): ?><option <?= ($data['filters']['type'] ?? '')===$t['name']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select></label><?php foreach (['min'=>'Minimum price ($)','max'=>'Maximum price ($)','beds'=>'Minimum bedrooms','baths'=>'Minimum bathrooms','area'=>'Minimum floor area'] as $k=>$label): ?><label class="field"><span><?= e($label) ?></span><input type="number" min="0" name="<?= $k ?>" value="<?= e($data['filters'][$k] ?? '') ?>" placeholder="Any"></label><?php endforeach ?><label class="field"><span>Amenity or accessibility</span><select name="amenity"><option value="">Any feature</option><?php foreach ($data['amenities'] as $a): ?><option value="<?= $a['id'] ?>" <?= ($data['filters']['amenity'] ?? '')==$a['id']?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach ?></select></label><label class="field"><span>Availability</span><select name="availability"><option value="">All available</option><option value="published" <?= ($data['filters']['availability'] ?? '')==='published'?'selected':'' ?>>Available</option><option value="under_offer" <?= ($data['filters']['availability'] ?? '')==='under_offer'?'selected':'' ?>>Under offer</option></select></label><input type="hidden" name="sort" value="<?= e($data['filters']['sort'] ?? 'newest') ?>"><button class="button"><?= icon('search') ?> Apply filters</button><a class="plain" href="/properties">Reset filters</a></form></aside><div class="search-results"><div class="search-toolbar"><span><b><?= $data['search']['total'] ?></b> homes to discover</span><div class="view-switch" aria-label="Results view"><button class="selected" data-view="list">List view</button><button data-view="map">Map & list</button></div><select data-sort aria-label="Sort properties"><?php foreach (['newest'=>'Recently listed','price_low'=>'Price: low to high','price_high'=>'Price: high to low','area'=>'Largest floor area'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($data['filters']['sort'] ?? 'newest')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></div><div class="map-view" hidden><div class="map-coast"></div><span class="map-label">Schematic view · approximate locations · not a street map</span><?php foreach ($data['search']['items'] as $i=>$p): ?><?php if ($p['location_privacy']!=='private'): ?><a class="map-marker" href="/property?id=<?= $p['id'] ?>" data-map-property="<?= $p['id'] ?>" data-marker-index="<?= $i ?>"><?= money($p['price_minor']) ?></a><?php endif ?><?php endforeach ?></div><div class="property-grid"><?php foreach ($data['search']['items'] as $p) require ROOT.'/templates/partials/property-card.php'; ?></div><?php if (!$data['search']['items']): ?><div class="empty"><h3>A different search may open new doors.</h3><p>Try widening your location or price range.</p><a class="button" href="/properties">Explore all homes</a></div><?php endif ?><nav class="pagination" aria-label="Search pages"><?php for($n=1;$n<=$data['search']['pages'];$n++): ?><a class="<?= $n===$data['search']['page']?'current':'' ?>" href="/properties?<?= e(http_build_query([...$data['filters'],'page'=>$n])) ?>"><?= $n ?></a><?php endfor ?></nav><div class="panel"><h3>Keep your search close.</h3><?php if ($user): ?><form class="form-row" method="post" action="/dashboard/action"><?= csrf() ?><input type="hidden" name="action" value="search_save"><input type="hidden" name="tab" value="searches"><input type="hidden" name="filters" value="<?= e(http_build_query($data['filters'])) ?>"><input class="input" name="name" placeholder="Name this search" required maxlength="100"><button class="button">Save search <?= icon('arrow') ?></button></form><p class="tiny">Alerts appear in your account when the scheduled alert command runs. Email and SMS are disabled.</p><?php else: ?><p>Sign in to save filters and receive in-app updates.</p><a class="text-link" href="/login">Sign in <?= icon('arrow') ?></a><?php endif ?></div></div></div>
